bool horizontalButtonVisible(const char*text){lv_obj_update_layout(lv_screen_active());auto*l=findText(lv_screen_active(),text,true);if(!l)return false;auto*button=lv_obj_get_parent(l);lv_area_t b,p;lv_obj_get_coords(button,&b);lv_obj_get_coords(lv_obj_get_parent(button),&p);return b.x1>=p.x1&&b.x2<=p.x2;}
bool controlsOverlap(lv_obj_t*a,lv_obj_t*b){lv_area_t x,y;lv_obj_get_coords(a,&x);lv_obj_get_coords(b,&y);return x.x1<=y.x2&&y.x1<=x.x2&&x.y1<=y.y2&&y.y1<=x.y2;}
